def _strip_bom(text):
    if text.startswith("\ufeff"):
        return text[1:]
    return text


def _read_csv(data, label):
    """Parse CSV text (or a list of rows) into (header, records).

    ``records`` is a list of dicts mapping the normalised header name to the
    raw cell text.  The input is never modified.
    """
    if data is None:
        return [], []
    if isinstance(data, (bytes, bytearray)):
        try:
            data = data.decode("utf-8-sig")
        except UnicodeDecodeError:
            raise ValueError("%s csv is not valid utf-8" % label)
    if isinstance(data, str):
        reader = csv.reader(io.StringIO(_strip_bom(data), newline=""))
        rows = [list(row) for row in reader]
    elif isinstance(data, (list, tuple)):
        rows = [list(row) for row in data]
    else:
        raise ValueError("%s csv must be a csv string" % label)

    # drop completely blank lines (but keep rows that carry data)
    rows = [row for row in rows if any((cell or "").strip() != "" for cell in row)]
    if not rows:
        return [], []

    header = [(name or "").strip().lower() for name in rows[0]]
    records = []
    for raw in rows[1:]:
        record = {}
        for index, name in enumerate(header):
            record[name] = raw[index"}

